import sqlite3
from datetime import datetime, timezone
from pathlib import Path

from flask import Flask, g, jsonify, request, render_template

DB = Path(__file__).parent / "shop.db"

app = Flask(__name__)


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db(seed=True):
    con = sqlite3.connect(DB)
    con.executescript(
        """
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            price REAL NOT NULL,
            stock INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty INTEGER NOT NULL,
            total REAL NOT NULL,
            created_at TEXT NOT NULL
        );
        """
    )
    if seed:
        n = con.execute("SELECT COUNT(*) FROM products").fetchone()[0]
        if n == 0:
            con.executemany(
                "INSERT INTO products (name, price, stock) VALUES (?, ?, ?)",
                [
                    ("Mechanical Keyboard", 89.99, 25),
                    ("Wireless Mouse", 34.50, 40),
                    ("USB-C Hub", 42.00, 18),
                    ("27\" 4K Monitor", 329.00, 10),
                    ("Laptop Stand", 27.95, 30),
                    ("Noise-Cancelling Headphones", 149.00, 12),
                    ("Webcam 1080p", 59.99, 22),
                    ("Desk Mat XL", 19.99, 50),
                ],
            )
    con.commit()
    con.close()


@app.route("/")
def index():
    return render_template("index.html")


@app.route("/api/products")
def api_products():
    rows = get_db().execute("SELECT id, name, price, stock FROM products ORDER BY id").fetchall()
    return jsonify([dict(r) for r in rows])


@app.route("/api/orders", methods=["POST"])
def api_orders():
    data = request.get_json(silent=True) or {}
    try:
        product_id = int(data.get("product_id"))
        qty = int(data.get("qty"))
    except (TypeError, ValueError):
        return jsonify({"error": "product_id and qty are required integers"}), 400
    if qty <= 0:
        return jsonify({"error": "qty must be positive"}), 400

    db = get_db()
    product = db.execute("SELECT id, name, price, stock FROM products WHERE id = ?", (product_id,)).fetchone()
    if product is None:
        return jsonify({"error": "product not found"}), 404
    if product["stock"] < qty:
        return jsonify({"error": f"insufficient stock: requested {qty}, available {product['stock']}"}), 409

    total = round(product["price"] * qty, 2)
    created_at = datetime.now(timezone.utc).isoformat()
    cur = db.execute(
        "INSERT INTO orders (product_id, qty, total, created_at) VALUES (?, ?, ?, ?)",
        (product_id, qty, total, created_at),
    )
    db.execute("UPDATE products SET stock = stock - ? WHERE id = ?", (qty, product_id))
    db.commit()
    return jsonify({"id": cur.lastrowid, "product_id": product_id, "product": product["name"], "qty": qty, "total": total, "created_at": created_at}), 201


@app.route("/api/orders/latest")
def api_orders_latest():
    rows = get_db().execute(
        """SELECT o.id, o.qty, o.total, o.created_at, p.name AS product
           FROM orders o JOIN products p ON p.id = o.product_id
           ORDER BY o.id DESC LIMIT 5"""
    ).fetchall()
    return jsonify([dict(r) for r in rows])


if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000)

